package com.yisy.modules.doramcu.admin.model;

import jakarta.persistence.*;

import java.time.LocalDateTime;

/**
 * JPA entity representing a health report generated by an AI admin.
 * Reports summarize activity, galaxy status, and LLM-generated recommendations
 * for a given time period (DAILY, WEEKLY, MONTHLY).
 */
@Entity
@Table(name = "ai_admin_health_reports", indexes = {
        @Index(name = "idx_aahr_admin", columnList = "ai_admin_id"),
        @Index(name = "idx_aahr_type", columnList = "report_type"),
        @Index(name = "idx_aahr_period", columnList = "period_start"),
        @Index(name = "idx_aahr_generated", columnList = "generated_at")
})
public class AiAdminHealthReport {

    @Id
    @GeneratedValue(strategy = GenerationType.AUTO)
    private Long id;

    /**
     * AI admin character who generated this report.
     */
    @Column(name = "ai_admin_id", nullable = false)
    private Long aiAdminId;

    /**
     * Type of report (DAILY, WEEKLY, MONTHLY).
     */
    @Enumerated(EnumType.STRING)
    @Column(name = "report_type", nullable = false, length = 10)
    private ReportType reportType;

    /**
     * Start of the reporting period.
     */
    @Column(name = "period_start", nullable = false)
    private LocalDateTime periodStart;

    /**
     * End of the reporting period.
     */
    @Column(name = "period_end", nullable = false)
    private LocalDateTime periodEnd;

    /**
     * When the report was generated.
     */
    @Column(name = "generated_at", nullable = false)
    private LocalDateTime generatedAt;

    /**
     * Total orders processed during the period.
     */
    @Column(name = "orders_processed", nullable = false)
    private Integer ordersProcessed = 0;

    /**
     * Orders completed successfully during the period.
     */
    @Column(name = "orders_completed", nullable = false)
    private Integer ordersCompleted = 0;

    /**
     * Orders that failed during the period.
     */
    @Column(name = "orders_failed", nullable = false)
    private Integer ordersFailed = 0;

    /**
     * Incidents handled during the period.
     */
    @Column(name = "incidents_handled", nullable = false)
    private Integer incidentsHandled = 0;

    /**
     * XP earned during the period.
     */
    @Column(name = "xp_earned", nullable = false)
    private Integer xpEarned = 0;

    /**
     * Galaxy health score (0-100).
     */
    @Column(name = "galaxy_health_score")
    private Integer galaxyHealthScore;

    /**
     * Number of active incidents at report time.
     */
    @Column(name = "active_incidents", nullable = false)
    private Integer activeIncidents = 0;

    /**
     * Text summary of the report period.
     */
    @Column(length = 4000)
    private String summary;

    /**
     * LLM-generated recommendations based on the report data.
     */
    @Column(name = "recommendations", length = 4000)
    private String recommendations;

    /**
     * Raw LLM analysis response for audit purposes.
     */
    @Column(name = "llm_analysis", length = 4000)
    private String llmAnalysis;

    public enum ReportType {
        DAILY,
        WEEKLY,
        MONTHLY
    }

    // ---------------------------------------------------------------
    // Getters and setters
    // ---------------------------------------------------------------

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getAiAdminId() {
        return aiAdminId;
    }

    public void setAiAdminId(Long aiAdminId) {
        this.aiAdminId = aiAdminId;
    }

    public ReportType getReportType() {
        return reportType;
    }

    public void setReportType(ReportType reportType) {
        this.reportType = reportType;
    }

    public LocalDateTime getPeriodStart() {
        return periodStart;
    }

    public void setPeriodStart(LocalDateTime periodStart) {
        this.periodStart = periodStart;
    }

    public LocalDateTime getPeriodEnd() {
        return periodEnd;
    }

    public void setPeriodEnd(LocalDateTime periodEnd) {
        this.periodEnd = periodEnd;
    }

    public LocalDateTime getGeneratedAt() {
        return generatedAt;
    }

    public void setGeneratedAt(LocalDateTime generatedAt) {
        this.generatedAt = generatedAt;
    }

    public Integer getOrdersProcessed() {
        return ordersProcessed;
    }

    public void setOrdersProcessed(Integer ordersProcessed) {
        this.ordersProcessed = ordersProcessed;
    }

    public Integer getOrdersCompleted() {
        return ordersCompleted;
    }

    public void setOrdersCompleted(Integer ordersCompleted) {
        this.ordersCompleted = ordersCompleted;
    }

    public Integer getOrdersFailed() {
        return ordersFailed;
    }

    public void setOrdersFailed(Integer ordersFailed) {
        this.ordersFailed = ordersFailed;
    }

    public Integer getIncidentsHandled() {
        return incidentsHandled;
    }

    public void setIncidentsHandled(Integer incidentsHandled) {
        this.incidentsHandled = incidentsHandled;
    }

    public Integer getXpEarned() {
        return xpEarned;
    }

    public void setXpEarned(Integer xpEarned) {
        this.xpEarned = xpEarned;
    }

    public Integer getGalaxyHealthScore() {
        return galaxyHealthScore;
    }

    public void setGalaxyHealthScore(Integer galaxyHealthScore) {
        this.galaxyHealthScore = galaxyHealthScore;
    }

    public Integer getActiveIncidents() {
        return activeIncidents;
    }

    public void setActiveIncidents(Integer activeIncidents) {
        this.activeIncidents = activeIncidents;
    }

    public String getSummary() {
        return summary;
    }

    public void setSummary(String summary) {
        this.summary = summary;
    }

    public String getRecommendations() {
        return recommendations;
    }

    public void setRecommendations(String recommendations) {
        this.recommendations = recommendations;
    }

    public String getLlmAnalysis() {
        return llmAnalysis;
    }

    public void setLlmAnalysis(String llmAnalysis) {
        this.llmAnalysis = llmAnalysis;
    }
}
